import Foundation

/// The sound a person's notifications play.
///
/// Apps may not use the iPhone's ringtones or alert tones, so besides the system default Closer
/// ships its own sounds in the app bundle and lets the user add their own (`custom`, see
/// `SoundLibrary`). The bundled sounds are generated by `scripts/generate-notification-sounds.py`;
/// `fileName` must match the files it writes.
nonisolated enum NotificationSound: Hashable, Identifiable, Codable {
    /// The iOS default sound for notifications.
    case standard
    case naehe
    case funke
    case tropfen
    case morgen
    case gruss
    /// A sound the user added, identified by `CustomSound.id`.
    case custom(UUID)

    /// Closer's own sounds, in the order they are offered.
    static let bundled: [NotificationSound] = [.naehe, .funke, .tropfen, .morgen, .gruss]

    /// Stable identifier, also the stored value: "naehe", "custom-<UUID>", …
    var id: String {
        switch self {
        case .standard: "standard"
        case .naehe: "naehe"
        case .funke: "funke"
        case .tropfen: "tropfen"
        case .morgen: "morgen"
        case .gruss: "gruss"
        case .custom(let id): "custom-\(id.uuidString)"
        }
    }

    /// Unknown values (e.g. a sound removed in a later version) fall back to `.standard`, so a
    /// person is never lost over their sound.
    init(id: String) {
        if let known = ([.standard] + Self.bundled).first(where: { $0.id == id }) {
            self = known
        } else if id.hasPrefix("custom-"), let uuid = UUID(uuidString: String(id.dropFirst("custom-".count))) {
            self = .custom(uuid)
        } else {
            self = .standard
        }
    }

    /// Name of a built-in sound. Custom sounds are named by the user, see
    /// `PeopleViewModel.title(for:)`.
    var title: String {
        switch self {
        case .standard: "Standard"
        case .naehe: "Nähe"
        case .funke: "Funke"
        case .tropfen: "Tropfen"
        case .morgen: "Morgen"
        case .gruss: "Gruss"
        case .custom: "Eigener Ton"
        }
    }

    var subtitle: String {
        switch self {
        case .standard: "Hinweiston des iPhones"
        case .naehe: "Zwei Töne, die sich finden"
        case .funke: "Hell und lebhaft"
        case .tropfen: "Kurz und leise"
        case .morgen: "Ruhig aufsteigend"
        case .gruss: "Ein freundliches Hallo"
        case .custom: "Von dir hinzugefügt"
        }
    }

    var isCustom: Bool {
        if case .custom = self { true } else { false }
    }

    /// File name iOS looks up for the notification: in the app bundle for Closer's sounds, in
    /// `Library/Sounds` for custom ones. `nil` for the system default.
    var fileName: String? {
        switch self {
        case .standard: nil
        case .custom(let id): "\(id.uuidString).caf"
        default: "closer-\(id).wav"
        }
    }

    init(from decoder: any Decoder) throws {
        self.init(id: try decoder.singleValueContainer().decode(String.self))
    }

    func encode(to encoder: any Encoder) throws {
        var container = encoder.singleValueContainer()
        try container.encode(id)
    }
}
